import { Injectable } from '@nestjs/common';
import { QueryRunner } from 'typeorm';
import { Shop } from '../../shop/entity/shop.entity';

@Injectable()
export class TenantMigrationService {
  async runMigrations(
    queryRunner: QueryRunner,
    schemaName: string,
    shop: Shop,
  ): Promise<void> {
    // Only allow schema names generated by our application.
    if (!/^shop_[a-f0-9]{32}$/.test(schemaName)) {
      throw new Error('Invalid tenant schema name.');
    }

    const schema = `"${schemaName}"`;

    // 1. Shop table
    await queryRunner.query(`
      CREATE TABLE ${schema}."shops" (
        "id" SERIAL PRIMARY KEY,
        "uuid" UUID NOT NULL UNIQUE,
        "name" VARCHAR(255) NOT NULL,
        "code" VARCHAR(100) NOT NULL UNIQUE,
        "schemaName" VARCHAR(255) NOT NULL UNIQUE,
        "isActive" BOOLEAN NOT NULL DEFAULT TRUE,
        "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
      )
    `);

    // 2. Users table
await queryRunner.query(`
  CREATE TABLE ${schema}."users" (
    "id" SERIAL PRIMARY KEY,
    "uuid" UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
    "firstName" VARCHAR(100) NOT NULL,
    "lastName" VARCHAR(100) NOT NULL,
    "email" VARCHAR(150) NOT NULL UNIQUE,
    "phoneNumber" VARCHAR(20),
    "password" VARCHAR NOT NULL,
    "profileImage" VARCHAR,
    "isActive" BOOLEAN NOT NULL DEFAULT TRUE,
    "isVerified" BOOLEAN NOT NULL DEFAULT FALSE,
    "isSuperAdmin" BOOLEAN NOT NULL DEFAULT FALSE,
    "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
  )
`);


    // 3. Items table
    await queryRunner.query(`
      CREATE TABLE ${schema}."items" (
        "id" SERIAL PRIMARY KEY,
        "uuid" UUID NOT NULL UNIQUE DEFAULT gen_random_uuid(),
        "name" VARCHAR(200) NOT NULL,
        "description" TEXT,
        "price" NUMERIC(15,2) NOT NULL DEFAULT 0,
        "quantity" NUMERIC(15,2) NOT NULL DEFAULT 0,
        "categoryId" INTEGER,
        "isActive" BOOLEAN NOT NULL DEFAULT TRUE,
        "createdAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        "updatedAt" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
        CONSTRAINT "FK_items_category"
          FOREIGN KEY ("categoryId")
          REFERENCES ${schema}."categories"("id")
          ON DELETE SET NULL
      )
    `);

  //4.. Save this shop's own record in its schema.
    await queryRunner.query(
      `
        INSERT INTO ${schema}."shops"
          ("id", "uuid", "name", "code", "schemaName", "isActive")
        VALUES ($1, $2, $3, $4, $5, $6)
      `,
      [
        shop.id,
        shop.uuid,
        shop.name,
        shop.code,
        shop.schemaName,
        shop.isActive,
      ],
    );

    // Keep the tenant shops table's ID sequence in sync.
    await queryRunner.query(`
      SELECT setval(
        pg_get_serial_sequence('${schemaName}.shops', 'id'),
        COALESCE((SELECT MAX("id") FROM ${schema}."shops"), 1),
        true
      )
    `);
  }
}